param(
  [switch]$Check,
  [switch]$Baseline,
  [switch]$CheckEncode,
  [switch]$CheckPatches,
  [switch]$FixPresets,
  [switch]$Apply,
  [string]$SourceDir = '',
  [string]$OutDir = "F:\_crystal-sandbox\rendered"
)
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'crystal-lock.ps1')
# P1 骨架版 crystal-build：只读总表、检查六处红线目标、渲染只写沙箱。
# 红线：六处现网生成物（r1-r6）本段一律不写；生成物头部规则 # GENERATED by crystal，勿手改。
$root = Split-Path -Parent $PSScriptRoot
$table = Join-Path $root 'crystal.json'
$logDir = Join-Path $root 'data\crystal\logs'
if (-not (Test-Path $logDir)) { New-Item -ItemType Directory -Force -Path $logDir | Out-Null }
$t = Get-Content -Raw -Encoding UTF8 $table | ConvertFrom-Json
if ($t.schemaVersion -ne 2) { throw 'crystal.json schemaVersion 必须为 2' }
$redline = @($t.renders | Where-Object { $_.status -like 'planned-redline*' })
Write-Output ("表头: writer=$($t._writer) writtenAt=$($t._writtenAt) schemaVersion=$($t.schemaVersion)")
Write-Output ("红线目标（本段只读不生成）共 $($redline.Count) 处：")
foreach ($r in $redline) { Write-Output ("  $($r.id) [$($r.kind)] $($r.target)") }
if ($CheckEncode) {
  # §16.6：产物编码校验（json 首字节 123、ps1 239 187 191、md 不带 BOM），不对就红 exit 1
  $targets = @()
  if ($SourceDir -ne '') { $targets = @(Get-ChildItem -Path $SourceDir -File -ErrorAction SilentlyContinue) }
  else { $targets = @(Get-ChildItem -Path $OutDir -File -ErrorAction SilentlyContinue) }
  if ($targets.Count -eq 0) { Write-Output '[RED] CheckEncode: 无文件可校验（-SourceDir 或 -OutDir 为空）'; exit 1 }
  $bad = 0
  foreach ($f in $targets) {
    $b = [IO.File]::ReadAllBytes($f.FullName)
    $ok = $false
    if ($f.Extension -eq '.json') { $ok = ($b.Length -gt 0 -and $b[0] -eq 123) }
    elseif ($f.Extension -eq '.ps1') { $ok = ($b.Length -gt 3 -and $b[0] -eq 239 -and $b[1] -eq 187 -and $b[2] -eq 191) }
    elseif ($f.Extension -eq '.md') { $ok = ($b.Length -eq 0 -or $b[0] -ne 239) }
    else { $ok = $true }
    if ($ok) { Write-Output ("[GREEN] 编码 ok: " + $f.FullName) }
    else { Write-Output ("[RED] 编码校验失败: " + $f.FullName + "（首字节不符：json 应 123、ps1 应 239 187 191、md 不应带 BOM）"); $bad++ }
  }
  if ($bad -gt 0) { exit 1 }
  exit 0
}
if ($CheckPatches) {
  # §16.7：patch 漂移检测侧——只报不改（stdout + alerts.log 黄行，带文件+行号；自动重建待授权）
  # 口径：每件 patch 尾部有 crystal 5 行标记块；漂移=标记块缺失、来源行缺失、或「来源=」行归一化后与 render-baseline.json 指纹不一致
  $srcDir = $SourceDir
  $r4 = $t.renders | Where-Object { $_.id -eq 'r4' } | Select-Object -First 1
  if ($srcDir -eq '') { $srcDir = $r4.target }
  $liveFiles = @(Get-ChildItem -Path $srcDir -File -Filter '*.patch.yml' -ErrorAction SilentlyContinue)
  $alertsP = ''
  . (Join-Path $PSScriptRoot 'crystal-fallback.ps1')
  $alertsP = Get-CrystalAlertsPath
  try{ if($null -ne $t.paths.alerts -and $t.paths.alerts -ne ''){ $alertsP=[string]$t.paths.alerts } }catch{}
  $sandboxHome='F:\_crystal-sandbox'
  $baselinePath='F:\crystal\data\render-baseline.json'
  try{
    if($null -ne $t.paths.sandbox -and $t.paths.sandbox -ne ''){ $sandboxHome=[string]$t.paths.sandbox }
    if($null -ne $t.paths.baseline -and $t.paths.baseline -ne ''){ $baselinePath=[string]$t.paths.baseline }
    elseif($null -ne $t.paths.dataHome -and $t.paths.dataHome -ne ''){ $baselinePath=Join-Path ([string]$t.paths.dataHome) 'render-baseline.json' }
  }catch{}
  if($OutDir -eq ''){ $OutDir = Join-Path $sandboxHome 'rendered' }
  $enc2 = New-Object Text.UTF8Encoding($false)
  $bPath = $baselinePath
  $baseMap = @{}
  try {
    $bl = Get-Content $bPath -Raw -Encoding UTF8 | ConvertFrom-Json
    foreach ($e in @($bl.entries)) {
      $fpv = ([string]$e.sourceFingerprint) -replace "\r?\n$",""
      $baseMap[[string]$e.path] = $fpv
      $leaf = Split-Path -Leaf ([string]$e.path)
      if ($leaf -and -not $baseMap.ContainsKey($leaf)) { $baseMap[$leaf] = $fpv }
    }
  } catch {}
  . (Join-Path $PSScriptRoot 'crystal-renderhash.ps1')
  $drift = 0
  foreach ($lf in $liveFiles) {
    $lines = @(Get-Content $lf.FullName -Encoding UTF8)
    $si = -1; $ei = -1
    for ($i = 0; $i -lt $lines.Count; $i++) {
      if ($si -lt 0 -and $lines[$i] -match 'GENERATED by crystal') { $si = $i }
      elseif ($si -ge 0 -and $lines[$i] -match 'crystal 生成段结束') { $ei = $i; break }
    }
    $srcLine = ''
    $srcLineNo = 0
    if ($si -ge 0) {
      $end = if ($ei -ge 0) { $ei } else { $lines.Count - 1 }
      for ($i = $si; $i -le $end; $i++) { if ($lines[$i] -match '来源=') { $srcLine = $lines[$i]; $srcLineNo = $i + 1; break } }
    }
    if ($si -lt 0) {
      $line2 = '[YELLOW] ' + (Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff') + ' module=renders fault=patch-drift msg=patch 漂移: ' + $lf.FullName + '（GENERATED 标记块缺失，应为文件尾部 crystal 生成段；只报不改）'
      Write-Output $line2
      try { [IO.File]::AppendAllText($alertsP, $line2+"`r`n", $enc2) } catch {}
      $drift++
    }
    elseif ($srcLineNo -eq 0) {
      $line2 = '[YELLOW] ' + (Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff') + ' module=renders fault=patch-drift msg=patch 漂移: ' + $lf.FullName + ' 第 ' + ($si + 1) + ' 行 GENERATED 头在、来源行缺失（只报不改）'
      Write-Output $line2
      try { [IO.File]::AppendAllText($alertsP, $line2+"`r`n", $enc2) } catch {}
      $drift++
    }
    else {
      $fp = Normalize-CrystalText $srcLine
      $bf = ''
      if ($baseMap.ContainsKey($lf.FullName)) { $bf = $baseMap[$lf.FullName] }
      if ($bf -eq '' -and $baseMap.ContainsKey($lf.Name)) { $bf = $baseMap[$lf.Name] }
      if ($bf -ne '' -and $fp -eq ($bf -replace "\r?\n$","")) { Write-Output ("[GREEN] patch 一致: " + $lf.FullName + "（来源行第 " + $srcLineNo + " 行与基线指纹一致）") }
      else {
        $why = '（来源行与基线指纹不一致'
        if ($bf -eq '') { $why = '（基线无此文件指纹' }
        $line2 = '[YELLOW] ' + (Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff') + ' module=renders fault=patch-drift msg=patch 漂移: ' + $lf.FullName + ' 第 ' + $srcLineNo + ' 行来源行 ' + $why + '；只报不改，自动重建待授权）'
        Write-Output $line2
        try { [IO.File]::AppendAllText($alertsP, $line2+"`r`n", $enc2) } catch {}
        $drift++
      }
    }
  }
  if ($drift -gt 0) { Write-Output ("[PATCH-DRIFT] 共 " + $drift + " 处漂移（只报不改）"); exit 1 }
  exit 0
}
if ($FixPresets) {
  # §16.7 自动重建 presets 生成段（脑公全权授权 m-mwmdh3vm-13a11f）：Stage1 只出沙箱 diff；-Apply 才写现网（先逐件 .bak 点名）
  $r4 = $t.renders | Where-Object { $_.id -eq 'r4' } | Select-Object -First 1
  $liveFiles = @(Get-ChildItem -Path $r4.target -File -ErrorAction SilentlyContinue)
  if ($liveFiles.Count -eq 0) { Write-Output '[FIXPRESETS] 通配无匹配，停手'; exit 2 }
  $diffDir = Join-Path $sandboxHome 'fixpresets'
  New-Item -ItemType Directory -Force -Path $diffDir | Out-Null
  $encF = New-Object Text.UTF8Encoding($false)
  $plugs = ''
  foreach ($pp in @($t.plugins)) {
    $plab = [string]$pp.kind
    if ($pp.note) { $plab = [string]$pp.note }
    if ($plugs -ne '') { $plugs += ' / ' }
    $plugs += ($pp.name + '(' + $plab + ')')
  }
  $diffAll = @()
  $blocked = $false
  foreach ($lf in $liveFiles) {
    $lines = @(Get-Content $lf.FullName -Encoding UTF8)
    $headIdx = -1; $tailIdx = -1
    for ($i = 0; $i -lt $lines.Count; $i++) {
      if ($lines[$i] -match 'GENERATED by crystal') { $headIdx = $i }
      if ($headIdx -ge 0 -and $lines[$i] -match 'crystal 生成段结束') { $tailIdx = $i; break }
    }
    if ($headIdx -lt 0 -or $tailIdx -lt 0) {
      $blocked = $true
      $diffAll += ('[BLOCK-MISSING] ' + $lf.Name + '：无完整 GENERATED 块（head=' + $headIdx + ' tail=' + $tailIdx + '），停手人工看')
      continue
    }
    $block = @(
      '# ===== GENERATED by crystal，勿手改 =====',
      ('# 来源=crystal.json plugins（总表），落地=' + (Get-Date -Format 'yyyy-MM-dd HH:mm:ss') + ' writer=alice'),
      '# 本文件是 build-agent-preset-patches.mjs 生成物；crystal 不改内容、只挂来源标记',
      ('# 总表 plugins 镜像：' + $plugs),
      '# ===== crystal 生成段结束 =====')
    $new = @()
    for ($i = 0; $i -lt $headIdx; $i++) { $new += $lines[$i] }
    foreach ($blk in $block) { $new += $blk }
    for ($i = $tailIdx + 1; $i -lt $lines.Count; $i++) { $new += $lines[$i] }
    [IO.File]::WriteAllLines((Join-Path $diffDir ($lf.Name + '.new')), $new, $encF)
    $bad = @()
    $maxL = [Math]::Max($lines.Count, $new.Count)
    for ($i = 0; $i -lt $maxL; $i++) {
      $a = '<EOF>'
      if ($i -lt $lines.Count) { $a = $lines[$i] }
      $b2 = '<EOF>'
      if ($i -lt $new.Count) { $b2 = $new[$i] }
      if ($a -ne $b2) {
        if (($a -match '^\s*#') -and ($b2 -match '^\s*#')) { $diffAll += ($lf.Name + ' L' + ($i + 1) + ' 注释行变化：' + $a + ' -> ' + $b2) }
        else { $bad += (($i + 1).ToString() + ': ' + $a + ' -> ' + $b2) }
      }
    }
    if ($bad.Count -gt 0) { $blocked = $true; $diffAll += ('[LOGIC-LINE] ' + $lf.Name + ' 逻辑行变化，停手先报：' + ($bad -join '；')) }
  }
  [IO.File]::WriteAllLines((Join-Path $diffDir 'diff.txt'), $diffAll, $encF)
  foreach ($dl in $diffAll) { Write-Output $dl }
  if ($blocked) { Write-Output '[FIXPRESETS-BLOCKED] 存在块缺失/逻辑行变化，不写现网，先报验收方'; exit 2 }
  if (-not $Apply) {
    Write-Output ('[FIXPRESETS-OK] Stage1 沙箱 diff 完成：' + (Join-Path $diffDir 'diff.txt') + '；写现网需加 -Apply（会先逐件 .bak-20261119 点名）')
    exit 0
  }
  $lkApply=Get-CrystalWriteLock -Target (Split-Path -Parent ([string]$r4.target)) -TimeoutSec 90
  if($null -eq $lkApply){ Write-Output '[FIXPRESETS-SKIP] 锁被占（[LOCK-SKIP] 已留痕），本次不写现网'; exit 0 }
  try{
    $applied = @()
    foreach ($lf in $liveFiles) {
      $bakP = $lf.FullName + '.bak-20261119-' + (Get-Date -Format 'HHmm')
      Copy-Item -Path $lf.FullName -Destination $bakP -Force
      Copy-Item -Path (Join-Path $diffDir ($lf.Name + '.new')) -Destination $lf.FullName -Force
      $applied += ($lf.Name + '（bak=' + (Get-Item $bakP).Length + 'B）')
    }
    foreach ($ap in $applied) { Write-Output ('[FIXPRESETS-APPLIED] ' + $ap) }
    Write-Output '[FIXPRESETS-APPLIED] 全部写完；请跑 -CheckPatches 期望 4 GREEN 与 doctor 期望 0红0黄13绿1灰'
    exit 0
  }finally{
    Release-CrystalWriteLock $lkApply
  }
}
if ($Check) {
  foreach ($r in $redline) {
    if (Test-Path $r.target) { Write-Output ("  $($r.id) 在场（未动）") } else { Write-Output ("  $($r.id) 不在场（本段不生成）") }
  }
  $qPath = if ($t.paths.queue) { [string]$t.paths.queue } else { (Join-Path $root 'data\crystal\queue.json') }
  $uPath = if ($t.paths.usage) { [string]$t.paths.usage } else { (Join-Path $root 'data\crystal\usage.log') }
  Write-Output ("queue.json 在场: " + (Test-Path $qPath) + " ($qPath)")
  Write-Output ("usage.log 在场: " + (Test-Path $uPath) + " ($uPath)")
  Write-Output 'CHECK 完'
  exit 0
}
if($Baseline){
  $bLib=Join-Path $PSScriptRoot 'crystal-renderhash.ps1'
  if(-not (Test-Path $bLib)){ throw 'crystal-renderhash.ps1 缺失，无法建基线' }
  . $bLib
  $bPath=$baselinePath
  $entries=@()
  foreach($r in $redline){
    $tp=[string]$r.target
    $files=@()
    if($tp -like '*\*'){ $files=@(Get-ChildItem -Path $tp -File -ErrorAction SilentlyContinue) }
    else{ if(Test-Path $tp){ $files=@(Get-Item $tp) } }
    foreach($fi in $files){
      $facts=Get-RenderNormFacts -Path $fi.FullName -Kind ([string]$r.kind)
      if($null -eq $facts){ Write-Output ("  !!! "+$r.id+' '+$fi.FullName+' 无法归一化（跳过）'); continue }
      $entries += [pscustomobject]@{ id=[string]$r.id; path=$fi.FullName; kind=[string]$r.kind; normHash=$facts.normHash; headerText=$facts.headerText; headerLine=$facts.headerLine; sourceFingerprint=$facts.sourceFingerprint; sourceLine=$facts.sourceLine }
    }
  }
  $bj=[ordered]@{}
  $bj['schemaVersion']=1
  $bj['builtAt']=Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff'
  $bj['_note']='内容级基线：归一化=CRLF/LF+行尾空白+时间戳<TS>+路径分隔符；合法重渲染判绿，仅头/来源行/内容对不上判黄'
  $bj['entries']=$entries
  [IO.File]::WriteAllText($bPath, ($bj | ConvertTo-Json -Depth 10), (New-Object Text.UTF8Encoding($false)))
  Write-Output ('BASELINE 完：'+$entries.Count+' 条 -> '+$bPath)
  foreach($e in $entries){ Write-Output ('  '+$e.id+' '+$e.path.Substring($e.path.LastIndexOf('\')+1)+' '+$e.normHash.Substring(0,8)+' H'+$e.headerLine+' S'+$e.sourceLine) }
  exit 0
}
# -Render：只写沙箱目录，生成六处草稿（每件带 GENERATED 头 + 来源行）；现网六件一律不写
New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
$enc = New-Object System.Text.UTF8Encoding($false)
$h = '# GENERATED by crystal，勿手改'
$stamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff'
$src = "来源=crystal.json writer=$($t._writer) writtenAt=$($t._writtenAt) 渲染=$stamp"
$made = @()

# r1 inject-table.json（chat/work 注入清单）
$inj = [ordered]@{}
$inj['_generated'] = $h
$inj['_source'] = $src
foreach ($m in @('chat','work')) { if ($t.modes.$m.inject) { $inj[$m] = @($t.modes.$m.inject | Where-Object { $_ -ne $null }) } }
$p = Join-Path $OutDir 'r1-inject-table.draft.json'
[IO.File]::WriteAllText($p, ($inj | ConvertTo-Json -Depth 10), $enc); $made += $p

# r2 qq-tool-restrict 白名单片段
$sb = New-Object Text.StringBuilder
[void]$sb.AppendLine($h); [void]$sb.AppendLine($src)
[void]$sb.AppendLine('// r2 草稿：qq-tool-restrict.mjs 白名单常量片段（实装时按现网文件结构插入）')
foreach ($m in @('chat','work')) {
  $ch = @($t.modes.$m.tools.chatOnlyExact | Where-Object { $_ -ne $null })
  if ($ch.Count -gt 0) { [void]$sb.AppendLine(('const CHAT_ONLY_' + $m.ToUpper() + ' = ' + ($ch | ConvertTo-Json -Compress) + ';')) }
  $al = @($t.modes.$m.tools.allow | Where-Object { $_ -ne $null })
  if ($al.Count -gt 0) { [void]$sb.AppendLine(('const ALLOW_' + $m.ToUpper() + ' = ' + ($al | ConvertTo-Json -Compress) + ';')) }
}
$p = Join-Path $OutDir 'r2-tool-whitelist.draft.js'
[IO.File]::WriteAllText($p, $sb.ToString(), $enc); $made += $p

# r3 bridge.js 模式判定片段
$sb = New-Object Text.StringBuilder
[void]$sb.AppendLine($h); [void]$sb.AppendLine($src)
[void]$sb.AppendLine('// r3 草稿：bridge.js 模式判定片段（实装时按现网文件结构插入）')
foreach ($m in @('work','chat')) {
  if ($t.triggers.$m) { [void]$sb.AppendLine(('const TRIGGER_' + $m.ToUpper() + ' = ' + ($t.triggers.$m | ConvertTo-Json -Compress) + ';')) }
}
$p = Join-Path $OutDir 'r3-mode-trigger.draft.js'
[IO.File]::WriteAllText($p, $sb.ToString(), $enc); $made += $p

# r4 presets patch 片段
$sb = New-Object Text.StringBuilder
[void]$sb.AppendLine($h); [void]$sb.AppendLine($src)
[void]$sb.AppendLine('# r4 草稿：presets\\*.patch.yml 片段（实装时按现网文件结构插入）')
foreach ($pl in @($t.plugins)) {
  [void]$sb.AppendLine(('- name: ' + $pl.name))
  foreach ($k in @('kind','enabled')) { if ($null -ne $pl.$k) { [void]$sb.AppendLine(('  ' + $k + ': ' + $pl.$k)) } }
  if ($pl.note) { [void]$sb.AppendLine(('  note: ' + $pl.note)) }
}
$p = Join-Path $OutDir 'r4-preset-patch.draft.yml'
[IO.File]::WriteAllText($p, $sb.ToString(), $enc); $made += $p

# r5 AGENTS.md 片段
$sb = New-Object Text.StringBuilder
[void]$sb.AppendLine($h); [void]$sb.AppendLine($src)
[void]$sb.AppendLine('# r5 草稿：AGENTS.md 片段（实装时按现网文件结构插入）')
[void]$sb.AppendLine('')
[void]$sb.AppendLine('## 工作档规矩（crystal 生成草稿）')
foreach ($m in @('work','chat')) {
  if ($t.modes.$m.lane) { [void]$sb.AppendLine(('- ' + $m + ' 档：' + ($t.modes.$m.lane | ConvertTo-Json -Compress))) }
}
if ($t.budget) { [void]$sb.AppendLine(('- 预算：' + ($t.budget | ConvertTo-Json -Compress))) }
$p = Join-Path $OutDir 'r5-agenda.draft.md'
[IO.File]::WriteAllText($p, $sb.ToString(), $enc); $made += $p

# r6 config.json 片段
$r6 = [ordered]@{}
$r6['_generated'] = $h
$r6['_source'] = $src
if ($t.channels) { $r6['channels'] = $t.channels }
if ($t.memory) { $r6['memory'] = $t.memory }
$p = Join-Path $OutDir 'r6-bridge-config.draft.json'
[IO.File]::WriteAllText($p, ($r6 | ConvertTo-Json -Depth 10), $enc); $made += $p

# manifest（红线清单 + 本段草稿清单）
$lines = @($h, $src)
foreach ($r in $redline) { $lines += "$($r.id)`t$($r.kind)`t$($r.status)`t$($r.target)" }
$lines += '-- 本段草稿（仅沙箱，现网未动） --'
foreach ($f in $made) { $lines += $f }
[IO.File]::WriteAllLines((Join-Path $OutDir 'manifest.txt'), $lines, $enc)
$json = $t | ConvertTo-Json -Depth 10
[IO.File]::WriteAllText((Join-Path $OutDir 'crystal-mirror.json'), $json, $enc)
Write-Output ('RENDER 完，草稿 ' + $made.Count + ' 件 + crystal-mirror.json')
foreach ($f in $made) { Write-Output ('  ' + $f) }
# §16.6 产物编码校验：ps1 必须带 BOM、json 首字节 123、md 不带 BOM；不对就红 exit 1
$encBad = 0
foreach ($f in $made) {
  $b3 = [IO.File]::ReadAllBytes($f)
  if ($f -like '*.ps1') { if (-not ($b3.Length -gt 3 -and $b3[0] -eq 239 -and $b3[1] -eq 187 -and $b3[2] -eq 191)) { Write-Output ("[RED] 产物编码错（ps1 应带 BOM）: " + $f); $encBad++ } }
  elseif ($f -like '*.json') { if ($b3.Length -eq 0 -or $b3[0] -ne 123) { Write-Output ("[RED] 产物编码错（json 首字节应 123）: " + $f); $encBad++ } }
  elseif ($f -like '*.md') { if ($b3.Length -gt 0 -and $b3[0] -eq 239) { Write-Output ("[RED] 产物编码错（md 不应带 BOM）: " + $f); $encBad++ } }
}
# §16.3 生成物扫描：不许出现 taskkill /T /F 组合（forbidden 口径）
$tkBad = 0
foreach ($f in $made) {
  $txt2 = Get-Content $f -Raw -Encoding UTF8
  if ($txt2 -match '(?i)taskkill[^\r\n]*\/T[^\r\n]*\/F') { Write-Output ("[RED] 生成物含禁词 taskkill /T /F: " + $f); $tkBad++ }
}
if ($encBad -gt 0 -or $tkBad -gt 0) { exit 1 }
Write-Output ('产物编码与禁词校验通过（' + $made.Count + ' 件）')
